extracted_python_code:
tac_by_country = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "Active")
).PARTITION(name="country_groups", by=country).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

result = Transactions.WHERE(
    (transaction_type == 'buy') & (DATEDIFF("days", date_time, 'now') <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(name="ticker_groups", by=(ticker_symbol)).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
).PARTITION(
    name="type_groups", by=(transaction_type)
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

sales_by_model_with_m5_vin = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).CALCULATE(
    car_make=UPPER(make),
    car_model=UPPER(model)
).PARTITION(
    name="model_groups", 
    by=(car_make, car_model)
).CALCULATE(
    make=car_make,
    model=car_model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    average_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

gpm_calculation = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

result = Sales.WHERE(
    HAS(
        car.inventory_snapshots.WHERE(
            (is_in_inventory == False) & (snapshot_date == sale_date)
        )
    ) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

cash_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

cars_in_inventory_latest_snapshot = Dealership.CALCULATE(
    latest_date=MAX(
        InventorySnapshots.WHERE(
            (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
        ).snapshot_date
    )
).InventorySnapshots.WHERE(
    (snapshot_date == latest_date) & (is_in_inventory == True)
).car.CALCULATE(
    _id=_id,
    make=make,
    model=model,
    year=year
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), "@gmail.com") | ENDSWITH(LOWER(email), "@yahoo.com")
        )
    )
)

filtered_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

avg_weight_drugalin = DermTreatment.CALCULATE(
    avg_weight=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

caw_male_patients = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

private_insured_patient_count = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'F') & (ins_type == 'private')))
)

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == 'biologic')) == 1
).PARTITION(
    name="states", by=(loc_state)
).CALCULATE(
    state=loc_state
)

treatments_by_insurance = Treatments.WHERE(YEAR(end_dt) == 2022).CALCULATE(
    ins_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=(ins_type)
).CALCULATE(
    insurance_type=ins_type,
    avg_pasi_score_d100=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(5, by=avg_pasi_score_d100.ASC())

top_specialties_by_drug_amount = Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    speciality=doctor.speciality
).PARTITION(
    name="specialty_groups", by=(speciality)
).CALCULATE(
    speciality=speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

recent_psoriasis_treatments_count = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (HAS(drug.fda_appr_dt) == 1) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6) &
            (end_dt <= DATETIME('now'))
        )
    )
)

avg_male_patient_age = DermTreatment.CALCULATE(
    avg_age=AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

user_avg_balances = UserBalances.WHERE(
    DATEDIFF("days", updated_at, DATETIME('now')) <= 7
).PARTITION(
    name="user_group", by=(user_id)
).CALCULATE(
    avg_user_balance=AVG(UserBalances.balance)
)

average_amb_result = Ewallet.CALCULATE(
    average_amb=AVG(user_avg_balances.avg_user_balance)
)

user_marketing_preferences = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

tuc_past_month = Ewallet.CALCULATE(
    total_user_sessions=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

result = Transactions.WHERE(
    (YEAR(created_at) == 2023) &
    (sender_type == 'user') &
    (status == 'completed')
).CALCULATE(
    month_date=DATETIME(created_at, 'start of month')
).PARTITION(
    name="monthly_transactions", by=(month_date)
).CALCULATE(
    month=month_date,
    num_active_users=NDISTINCT(Transactions.sender_id)
).ORDER_BY(
    month.ASC()
)

distinct_merchant_ids = Transactions.WHERE(receiver_type == '1').PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(notification_type == 'transaction').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

median_merchant_balance = Ewallet.CALCULATE(
    median_balance=MEDIAN(
        Merchants.WHERE(
            (status == 'active') & CONTAINS(LOWER(category), 'retail')
        ).balances.WHERE(
            RANKING(by=updated_at.DESC(), per="Merchants") == 1
        ).balance
    )
)

result = UserSessions.PARTITION(name="sessions_by_device", by=(device_type)).CALCULATE(
    device_type=device_type,
    avg_session_duration_seconds=AVG(
        DATEDIFF("seconds", sessions_by_device.session_start_ts, sessions_by_device.session_end_ts)
    )
)
